    $scope.selectConversation = function(data) {
      if (data.select_conversation !== undefined) {
        $timeout(function() {
          var select_conversation;
          for (var i = 0, len = data.conversations.length; i < len; i++) {
            if (data.select_conversation.uid == data.conversations[i].uid && data.select_conversation.uid_type == data.conversations[i].uid_type) {
              select_conversation = data.conversations[i];
              break;
            }
          }

          // if not displayed push into conversations. Move to top.
          var new_timestamp = $scope.conversations[Object.keys($scope.conversations)[0]].last_message_ts + 1;
          if (select_conversation === undefined) {
            data.select_conversation.last_message_ts = new_timestamp;
            $scope.conversations[data.select_conversation.id] = data.select_conversation;
          } else
            select_conversation.last_message_ts = new_timestamp;

          $timeout(function() { angular.element('#conversations-list').children(':first').children(':first').triggerHandler('click'); });
        });
      }
    };


    $scope.messageTrackingFunction = function(message) {
      return message.msg_type + "-" + message.id.toString();
    };

    $scope.imageTrackingFunction = function(image) {
      return 'Image-' + image.ref.toString();
    };


    $scope.messageInView = function(index) {
      var message = $scope.selected_conversation_messages[index];
      if (message.unread) {
        message.unread = false;
        $scope.markMessagesAsRead($scope.current_chat_conversation.id, message.id);
      }
    };


    // Bind plugins to textbox
    // should only bind once...add check!!!!!!!!!!!!!!
    // setTimeout(function(){ BindPlugins.now() }, 0);
    var messages_page = 1;
    $scope.status = { loading: false, /* loaded: false */ };
    $scope.selected_conversation = {};
    $scope.getConversationMessages = function(conversation, from_conversations_list) {
      var deferred = $q.defer();

      // don't get messages if user clicks again on current conversation
      if (!(from_conversations_list && conversation.id == $scope.selected_conversation.id)) {
        //console.log(conversation);
        // highlight conversation
        $scope.current_chat_conversation = conversation;

        // a new conversation is selected, reset
        if ($scope.selected_conversation.id != conversation.id) {
          messages_page = 1;
          $scope.selected_conversation_messages = [];
        }

        // Pull messages if you click on another conversation, even if the current one is loading
        // Pull messages for the current conversation if it isnt loading
        if (!$scope.status.loading || conversation.id != $scope.selected_conversation.id) {
          $scope.selected_conversation = conversation;
          $scope.status.loading = true;

          conversationService.getConversationMessages(conversation.id, messages_page)
          .then(function(data) {
            if (conversation.id == $scope.selected_conversation.id) {
              if (data.messages.length > 0) {
                messages_page += 1;
                for (var i = 0; i < data.messages.length; i++) { 
                  data.messages[i].unread = false;
                  $scope.selected_conversation_messages.unshift(data.messages[i]); 
                }
                //$scope.status.loaded = ($scope.selected_conversation_messages.length > 0);  // might not need this line
                //$scope.markMessagesAsRead(conversation.id, data.unread_ids);
                $scope.status.loading = false;

                // Bind plugins to textbox
                // should only bind once...add check!!!!!!!!!!!!!!
                //$timeout(function(){ BindPlugins.now() }, 0);

                deferred.resolve();
              } else
                $scope.rejectPromise(false, 'no messages', deferred);
            } else
              $scope.rejectPromise(false, 'viewing anothe conversation', deferred)
          }, function(data) {
            $scope.rejectPromise(false, 'get more messages failed', deferred)
          });
        } else
          deferred.reject();
      } else
        deferred.reject();

      return deferred.promise;
    };

    $scope.rejectPromise = function(status, msg, obj) {
      $scope.status.loading = status;
      console.log(msg);
      obj.reject();
    }

    $scope.markMessagesAsRead = function(conversation_id, unread_ids) {
      conversationService.markMessageAsRead(conversation_id, unread_ids)
      .then(function(re) {
        var unread_ids = unread_ids.split(",");
        var unread_diff = $scope.global_unread_count - unread_ids.length;
        $scope.global_unread_count = (unread_diff > 0) ? unread_diff : 0;
        $scope.conversations[conversation_id].unread_count -= unread_ids.length;
        console.log('marked as read');
      }, function(re) {
        console.log('markes as read Failed');
      });
    };

    $scope.sendConversationMessage = function(new_message, channel) {
      $scope.is_sending = true;
      $scope.send_msg_btn = "Sending...";
      console.log(new_message);

      if ((new_message == undefined) || (new_message.text == '') || (new_message.text.length > $scope.char_limit)) {
        alert('Maximum ' + $scope.char_limit + ' characters.');
        $scope.enable_msg_btn();
      } else {
        var conversation_id = $scope.selected_conversation.id;
        conversationService.markMessageAsRead(conversation_id, new_message.text, channel)
        .then(function(data) {
          // ensure we still have the right conversation
          if ($scope.selected_conversation.id == conversation_id)
            $scope.selected_conversation_messages.push(data);
          new_message.text = '';
          console.log('sent message');
        }, function(data) {
          console.log('unable to send message');
          console.log(data)
        })
        .finally(function() { $scope.enable_msg_btn(); });
      };
    };

    $scope.enable_msg_btn = function() {
      $scope.is_sending = false;
      $scope.send_msg_btn = "SEND";
    };

    // MMS
    // Twilio supports only gif, png and jpeg
    $scope.handleFile = function(file, errFiles) {
      $scope.errFile = errFiles && errFiles[0];
      console.log(errFiles)
      if (file) {
        if (file.type.match('image')) {
          $scope.selected_file = file;
          // show preview
          $('#mms-img-preview').lightbox_me({ centered: true })
        } else
          console.log('unsupported type');
      } else if (errFiles.length > 0) {
        if(errFiles[0].$errorMessages.maxSize) console.log('file size is too large');
      }
    };

    $scope.cancelMMS = function() { $('#mms-img-preview').trigger('close'); };

    $scope.sendMMS = function(channel) {
      $scope.is_sending = true;
      $scope.send_mms_btn = "SENDING MMS";
      var file = $scope.selected_file;
      var conversation_id = $scope.selected_conversation.id;
      conversationService.sendConversationMMS(conversation_id, file, $scope.mms_text, channel)
      .then(function (data) {
        if ($scope.selected_conversation.id == conversation_id)
          $scope.selected_conversation_messages.push(data);
        // wipe file picker?
        console.log('mms sent');
      }, function (response) {
        console.log('unable to send mms');
      })
      .finally(function() {
        $('#mms-img-preview').trigger('close');
        $scope.is_sending = false;
        $scope.send_mms_btn = "SEND MMS";
      });
    }
    // End MMS


    // Transactions
    $scope.displayChargeForm = function() {
      $('#chargeFormBox').lightbox_me({
        centered: true,
        onLoad: function() { $('#chargeForm').find('input:first').focus(); }
      });
    };


    $scope.hashtagSelected = function(selected) { $scope.charge_data.hashtag_id = (selected) ? selected.originalObject.id : null; };
    $scope.hashtagsApiErrorHandler = function(selected) { alert('couldnt retrieve your tags'); };

    $scope.disableChargeButton = function(chargeForm) {
      return $scope.selected_conversation.id === undefined || chargeForm.$invalid || $scope.is_sending;
    }

    // function to submit the form after all validation has occurred
    $scope.submitChargeForm = function(isValid) {
      if (isValid) {
        $scope.is_sending = true;
        $scope.charge_btn = "Please wait...";
        $scope.charge_data.user_id = $scope.selected_conversation.uid;
        $scope.charge_data.item_name = document.getElementById('find-hashtag_value').value;
        $scope.charge_data.amount = $scope.charge.amount;
        $scope.charge_data.notes = ($scope.charge.notes) ? $scope.charge.notes : '';
        $scope.charge_data.capture = ($scope.charge.authorize) ? $scope.charge.authorize : false;
        console.log($scope.charge_data);

        transactionService.createCharge($scope.charge_data)
        .then(function (data) {
          console.log('charge complete');
          console.log(data)
        }, function (response) {
          console.log('unable to charge customer');
          console.log(response);
        })
        .finally(function() {
          $scope.is_sending = false;
          $scope.charge_btn = "CHARGE";
        });
      }
    };
