$(document).ready(function () {

  var query = "";

  $('.article-rating-button').attr('disabled', false)

  $('#kb-search').on('input', function (e) {
    e.preventDefault();
    get_results();
  });

  $("#kb-search-form").submit(function(e) {
    e.preventDefault();
    get_results();
  });

  $('.article-rating-button').on('click', function(e){
    e.preventDefault();
    var vote = $(this).text();
    if ($(this).attr('disabled') !== 'disabled') {
      count_vote(vote, $('html').data("article-url"));
      voteButtonCheck(vote)
    } 
  })

  function voteButtonCheck(vote) {
    if (vote === 'Yes') {
      $('#up-rating-button').attr("disabled", true);
      $('#down-rating-button').attr("disabled", false);
    } else {
      $('#up-rating-button').attr("disabled", false);
      $('#down-rating-button').attr("disabled", true);
    }
  }

  function count_vote(vote, url) {
    $.ajax({
      url: "/v1/knowledge_bases/" + url + "/rating.json",
      data: { vote: vote }
    })
    .done(function(data, textStatus, jqXHR) { console.log(data); });
  }

  function get_results() {
    var new_query = $('#kb-search').val().trim();
    if ((query != new_query) && (new_query != "")) {
      query = new_query;
      var remote_data = [];
      $.ajax({
        url: "/v1/knowledge_bases.json",
        data: { query: new_query }
      })
      .done(function(data, textStatus, jqXHR) { console.log(data); remote_data = data.results; })
      .always(function(data, textStatus, errorThrown) { setKB(remote_data); });
    } else if (query == new_query) {
    } else {
      query = "";
      $('#kb-search-title, #kb-search-results').html("");  
      $("#kb-content").show();
    }
  };

  function setKB(kbList) {
    $("#kb-content").hide();
    $('#kb-search-results').html("");  
    if (kbList.length == 0) {
      $('#kb-search-title').html('<div class="search_value w-container">We couldn\'t find any results for: ' + query + '</div>');
    } else {
      $('#kb-search-title').html('<div class="search_value w-container">Search results for: ' + query + '</div>');
      $.each(kbList, function(index, item) {
        var created_at = moment(item.created_at, "YYYYMMDD").fromNow();
        $('#kb-search-results').append(
          '<div class="article static-page-content-wrapper w-container">\
            <a href="' + item.url + '">' + item.title + '</a>\
            <p class="article-preview">' + item.raw_content.substring(0,29) + '</p>\
            <img class="article-author" height="30" src="http://uploads.webflow.com/5767087cbd63608e7eb4abdc/586da5db511381a742ba3da1_Edwin%202.jpg" width="30">\
            <div class="author-info">By <span class="author-name">' + item.author + '</span> &nbsp;| &nbsp;' + created_at + '</div>\
          </div>');
      });  
    }
  };

});
// flash success for all types of flash messages
// the first parameter is message and second parameter is type eg: success
var FlashHandler = new function() {
  // toast message for error, success, notice
  this.setFlashMessage = function(msg, type){
    var typeObj = { 'notice': 'success', 'warning': 'info', 'error':'error' };
    var messageToSet = typeObj[type] || 'Attention';
    // new PNotify({
    //   title: messageToSet + '!!',
    //   text: arrayToString(msg),
    //   type: messageToSet,
    //   hide: true
    // });
    showToastr (messageToSet, arrayToString(msg));
    $('.toasters-close').on('click', function (e) {
      e.preventDefault();
      debugger
      $('.toasters').fadeOut(3000);
    } );
  };

  function showToastr (type, message) {
    var class_name = (type === 'error') ? 'failure toasters' : 'toasters' ;
    $('body').append('<div class="'+class_name+'">\
      <div class="toaster-row w-row">\
        <div class="toaster-row-column-1 w-col w-col-11">\
          <div class="shrink-text toaster-text">\
            '+message+'\
          </div>\
        </div>\
        <div class="toaster-row-column-2 w-clearfix w-col w-col-1">\
          <div class="toaster-font-awesome toasters-close"></div>\
        </div>\
      </div>\
    </div>')
  }

  // Confirmation Dialog for event
  var stack = {'dir1': 'down', 'dir2': 'right', 'modal': true};
  this.setConfirmationDialog = function (selector, title, confirmText, isConfirm){
    (new PNotify({
      title: title,
      text: confirmText,
      icon: 'glyphicon glyphicon-question-sign',
      hide: false,
      confirm: {
        confirm: true
      },
      buttons: {
        closer: false,
        sticker: false
      },
      history: {
        history: false
      },
      addclass: 'stack-modal',
      stack: stack
    })).get().on('pnotify.confirm', function() {
      $(selector).attr(isConfirm, true);
      $(selector)[0].click();
    }).on('pnotify.cancel', function() {
      return false;
    });
  };

  // when multiple flash message are present it converts it to multiline flash message
  function arrayToString(value){
    if ($.isArray(value)) {
      messageString = ''
      $.each(value, function(index, value){ messageString += value + "\n"; })
      return messageString;
    } else {
      return value;
    }
  }

}
;
